// Rotate the correct option without changing its identity between languages.
export const awsExercisesByChapter = Object.fromEntries(Object.entries(chapters).map(([chapterId, questions]) => [chapterId,
  [...questions,...awsPracticeReviewExercises.filter(item=>item.chapterId===Number(chapterId))].map((item, index) => {
    const answer = (Number(chapterId) + index) % item.options.length;
    const options = [...item.options];
    [options[0], options[answer]] = [options[answer], options[0]];
    const practiceQuestion = item.practiceQuestionNumber ? awsQuestions.find(question=>question.number===item.practiceQuestionNumber) : undefined;
    return { ...item, options, answer, id:`aws-${chapterId}-${index+1}`, chapterId:Number(chapterId),
      source:item.source || 'original-handbook-review',
      ...(practiceQuestion ? {practiceSourcePages:practiceQuestion.sourcePages,practiceSourceAnswerLetters:practiceQuestion.answers} : {}),
    };
  }),
]));
